 */
export function getTableRowsSql({
  table,
  filters = [],
  sorts = [],
  page,
  limit,
  maxCharacters = MAX_CHARACTERS,
  maxArraySize = MAX_ARRAY_SIZE,
}: GetTableRowsArgs): string {
  const columns = table.columns ?? []

  // Keep the column selection order stable based on ordinal_position
  const orderedColumns = [...columns].sort((a, b) => a.ordinal_position - b.ordinal_position)

  // Build the select expressions, applying truncation only to the columns that need it
  const selectExpressions = orderedColumns.map((column) => {
    const col = ident(column.name)
    const isArray = column.data_type.toLowerCase() === 'array'
    const format = column.format.toLowerCase()
    const isTextOrJson = TEXT_TYPES.includes(format) || JSON_TYPES.includes(format)

