// Max number of elements to return for array based columns
export const MAX_ARRAY_SIZE = 50

// Default number of rows to return per page
export const DEFAULT_PAGE_SIZE = 100

// Any table-like entity that we're able to fetch rows from
export type TableLikeEntity = PGTable | PGView | PGForeignTable | PGMaterializedView

export interface GetTableRowsArgs {
  table: TableLikeEntity
  filters?: Filter[]
  sorts?: Sort[]
  page?: number
  limit?: number
  maxCharacters?: number
  maxArraySize?: number
}

// Text and JSON types whose values could grow large and hence should be truncated
const TEXT_TYPES = ['text', 'varchar', 'char', 'character varying', 'character']
const JSON_TYPES = ['json', 'jsonb']

function getPagination(page?: number, size: number = DEFAULT_PAGE_SIZE) {
  const limit = size
  const from = page ? page * limit : 0
  const to = page ? from + size - 1 : size - 1

  return { from, to }
}

// Return the primary key columns if they exist, otherwise return the first column
// to use as a default sort
export function getDefaultOrderByColumns(table: {
  primary_keys: Array<{ name: string }>
  columns: Array<{ name: string }>
}): string[] {
  const primaryKeyColumns = table.primary_keys?.map((pk) => pk.name) ?? []
  const columns = table.columns ?? []

  if (primaryKeyColumns.length === 0 && columns.length === 0) {
    return []
  }

  if (primaryKeyColumns.length > 0) {
    return primaryKeyColumns
  }

  return [columns[0].name]
}

/**
 * Generates a SQL SELECT statement to safely fetch rows from any table-like entity
 * (tables, views, materialized views and foreign tables).
 *
 * Large text/JSON columns and array columns are truncated on the database side so that
 * the payload stays reasonable, while all other columns are selected as-is.
 */
export function getTableRowsSql({
  table,
  filters = [],
  sorts = [],
  page,
  limit,
  maxCharacters = MAX_CHARACTERS,
  maxArraySize = MAX_ARRAY_SIZE,
}: GetTableRowsArgs): string {
  const columns = table.columns ?? []

  // Keep the column selection order stable based on ordinal_position
  const orderedColumns = [...columns].sort((a, b) => a.ordinal_position - b.ordinal_position)

  // Build the select expressions, applying truncation only to the columns that need it
  const selectExpressions = orderedColumns.map((column) => {
    const col = ident(column.name)
    const isArray = column.data_type.toLowerCase() === 'array'
    const format = column.format.toLowerCase()
    const isTextOrJson = TEXT_TYPES.includes(format) || JSON_TYPES.includes(format)

    if (isArray) {
      return `case
    when octet_length(${col}::text) > ${maxCharacters}
    then (select array_cat(${col}[1:${maxArraySize}]::text[], array['...']))::text[]
    else ${col}::text[]
end`
    }

    if (isTextOrJson) {
      return `case
    when octet_length(${col}::text) > ${maxCharacters}
    then left(${col}::text, ${maxCharacters}) || '...'
    else ${col}::text
end as ${col}`
    }

    return col
  })

  const selectClause = selectExpressions.length > 0 ? selectExpressions.join(',\n  ') : '*'

  // If sorts is empty, use the primary key (or first column) as the default sort
  let appliedSorts = sorts
  if (appliedSorts.length === 0) {
    const defaultOrderByColumns = getDefaultOrderByColumns({
      primary_keys: (table as PGTable).primary_keys ?? [],
      columns,
    })
    appliedSorts = defaultOrderByColumns.map((column) => ({
      table: table.name,
      column,
      ascending: true,
      nullsFirst: false,
    }))
  }

  // getPagination is expecting to start from 0
  const { from, to } = getPagination((page ?? 1) - 1, limit)
  const pagination: QueryPagination = { limit: to - from + 1, offset: from }

  return selectQuery({ name: table.name, schema: table.schema }, selectClause, {
    filters,
    sorts: appliedSorts,
    pagination,
  })
}

export default {
  getDefaultOrderByColumns,
  getTableRowsSql,
}
